-- =============================================================================
-- CryoBackup console schema  (SQLite, WAL)            migrations 0001_initial..0003_fleet_start_lease
-- Companion to architecture.md (section 3). ADR 0002 D3: modernc.org/sqlite.
--
-- CONVENTIONS
--   ids     TEXT PRIMARY KEY holding a 26-char ULID generated by the application,
--           except where a natural key is correct (settings.key, job_state.name,
--           snapshots (device_id, snapshot_id), usage_samples (device_id, sampled_at),
--           device_presence.device_id, maintenance_schedule.device_id).
--   times   INTEGER, milliseconds since the Unix epoch, UTC. Columns end in *_at
--           (audit_events uses occurred_at; recon calls it "at"). NOT NULL unless
--           the event may not have happened yet. Display timezone is applied at
--           render time only. High-volume agent-supplied timestamps carry a
--           >= 1e12 CHECK so a seconds-vs-milliseconds bug is rejected at insert.
--   json    TEXT with CHECK (json_valid(col)).
--   enums   CHECK (col IN (...)); the vocabulary is the one in recon section 6 and
--           the feature matrix, extended only where architecture.md says so.
--   bools   INTEGER 0/1 with a CHECK.
--   every table has created_at; mutable tables also have updated_at.
--   No secrets in this file or in plaintext columns: *_hash columns hold hashes,
--   *_wrapped columns hold AES-256-GCM ciphertext under keys derived (HKDF) from
--   the console master key, which is never stored in the database.
--   Access control: SQLite has no row-level security. Customer scoping
--   (admin_users.customer_scope) is enforced in the store layer; see
--   architecture.md section 3.
-- =============================================================================

-- Set by the application on EVERY connection (modernc.org/sqlite); repeated here
-- so ad-hoc sqlite3 sessions and the DDL test behave identically.
PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;

-- -----------------------------------------------------------------------------
-- 1. schema_migrations
-- -----------------------------------------------------------------------------
CREATE TABLE schema_migrations (
  version     INTEGER PRIMARY KEY CHECK (version > 0),
  name        TEXT    NOT NULL,
  checksum    TEXT    NOT NULL,
  created_at  INTEGER NOT NULL                      -- time the migration was applied
);

-- -----------------------------------------------------------------------------
-- 2. settings   (recon: Setting)  global key/value; secrets are references only
-- -----------------------------------------------------------------------------
CREATE TABLE settings (
  key         TEXT    PRIMARY KEY CHECK (length(key) BETWEEN 1 AND 128),
  value       TEXT    NOT NULL CHECK (json_valid(value)),
  updated_by  TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
);
CREATE INDEX idx_settings_updated_by ON settings(updated_by);

-- -----------------------------------------------------------------------------
-- 3. storage_targets   (recon: StorageTarget)
--    max_concurrent_backups (migration 0003, ADR 0005): the fleet cap, live start
--    leases per target; 0 = unlimited. It sits on the updated_at line because
--    that is where SQLite's ALTER TABLE ... ADD COLUMN writes it in sqlite_master,
--    and the migrated schema must equal this file (DH20).
-- -----------------------------------------------------------------------------
CREATE TABLE storage_targets (
  id                          TEXT    PRIMARY KEY CHECK (length(id) = 26),
  name                        TEXT    NOT NULL COLLATE NOCASE UNIQUE CHECK (length(name) BETWEEN 1 AND 100),
  provider                    TEXT    NOT NULL CHECK (provider IN ('wasabi','backblaze_b2','idrive_e2','aws_s3','s3_compatible')),
  endpoint                    TEXT    NOT NULL,
  region                      TEXT,
  bucket                      TEXT    NOT NULL,
  prefix                      TEXT    NOT NULL DEFAULT '',
  gateway_url                 TEXT    NOT NULL,     -- URL agents use for the restic REST gateway
  versioning                  INTEGER NOT NULL DEFAULT 0 CHECK (versioning IN (0,1)),
  object_lock_mode            TEXT    NOT NULL DEFAULT 'none' CHECK (object_lock_mode IN ('none','governance')),  -- compliance mode is unsafe with restic (engine 4.5): not representable
  object_lock_days            INTEGER CHECK (object_lock_days IS NULL OR object_lock_days > 0),
  min_storage_days            INTEGER NOT NULL DEFAULT 0 CHECK (min_storage_days >= 0),
  default_prune_cadence_days  INTEGER NOT NULL DEFAULT 30 CHECK (default_prune_cadence_days BETWEEN 1 AND 366),
  credential_ref              TEXT    NOT NULL,     -- NAME of the env var / mounted secret on the admin-path host; never the secret
  soft_quota_bytes            INTEGER CHECK (soft_quota_bytes IS NULL OR soft_quota_bytes > 0),
  is_default                  INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0,1)),
  archived_at                 INTEGER,
  created_at                  INTEGER NOT NULL,
  updated_at                  INTEGER NOT NULL, max_concurrent_backups INTEGER NOT NULL DEFAULT 0 CHECK (max_concurrent_backups >= 0),
  CHECK ((object_lock_mode = 'governance') = (object_lock_days IS NOT NULL))
);
CREATE UNIQUE INDEX uq_storage_targets_default  ON storage_targets(is_default) WHERE is_default = 1;
CREATE UNIQUE INDEX uq_storage_targets_location ON storage_targets(endpoint, bucket, prefix);

-- -----------------------------------------------------------------------------
-- 4. admin_users   (recon: AdminUser)        defined early: many FKs point here
--    totp_last_step (migration 0004, M2-W1A): the RFC 6238 step of the last TOTP
--    code used; a code is accepted only for a later step (replay guard). It sits
--    on the updated_at line because that is where SQLite's ALTER TABLE ... ADD
--    COLUMN writes it in sqlite_master, and the migrated schema must equal this
--    file (DH20).
-- -----------------------------------------------------------------------------
CREATE TABLE admin_users (
  id                   TEXT    PRIMARY KEY CHECK (length(id) = 26),
  username             TEXT    NOT NULL COLLATE NOCASE UNIQUE CHECK (length(username) BETWEEN 1 AND 100),
  email                TEXT    NOT NULL COLLATE NOCASE,
  display_name         TEXT,
  role                 TEXT    NOT NULL CHECK (role IN ('owner','admin','operator','read_only')),
  customer_scope       TEXT    CHECK (customer_scope IS NULL OR json_valid(customer_scope)),  -- JSON array of customer ids; NULL = all customers. Not an FK: deleted customers simply drop out.
  password_hash        TEXT,                        -- argon2id PHC string; NULL for OIDC-only accounts
  totp_secret_wrapped  BLOB,
  totp_enrolled_at     INTEGER,
  oidc_subject         TEXT,
  ip_allowlist         TEXT    CHECK (ip_allowlist IS NULL OR json_valid(ip_allowlist)),
  must_change_password INTEGER NOT NULL DEFAULT 0 CHECK (must_change_password IN (0,1)),
  failed_login_count   INTEGER NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0),
  locked_until         INTEGER,
  last_login_at        INTEGER,
  last_login_ip        TEXT,
  disabled_at          INTEGER,
  created_at           INTEGER NOT NULL,
  updated_at           INTEGER NOT NULL, totp_last_step INTEGER,
  CHECK (password_hash IS NOT NULL OR oidc_subject IS NOT NULL),
  CHECK (role IN ('operator','read_only') OR customer_scope IS NULL),     -- only operator/read_only may be customer-scoped
  CHECK ((totp_secret_wrapped IS NULL) = (totp_enrolled_at IS NULL))
);
CREATE UNIQUE INDEX uq_admin_users_oidc ON admin_users(oidc_subject) WHERE oidc_subject IS NOT NULL;
CREATE INDEX idx_admin_users_role ON admin_users(role);

-- -----------------------------------------------------------------------------
-- 5. admin_recovery_codes   (AdminUser.recovery_codes_hash[] as rows: atomic one-time use)
-- -----------------------------------------------------------------------------
CREATE TABLE admin_recovery_codes (
  id          TEXT    PRIMARY KEY CHECK (length(id) = 26),
  admin_id    TEXT    NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  code_hash   TEXT    NOT NULL UNIQUE,
  used_at     INTEGER,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
);
CREATE INDEX idx_admin_recovery_codes_admin ON admin_recovery_codes(admin_id);

-- -----------------------------------------------------------------------------
-- 6. admin_webauthn_credentials   (AdminUser.webauthn_credentials[], matrix: should)
-- -----------------------------------------------------------------------------
CREATE TABLE admin_webauthn_credentials (
  id             TEXT    PRIMARY KEY CHECK (length(id) = 26),
  admin_id       TEXT    NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  credential_id  BLOB    NOT NULL UNIQUE,
  public_key     BLOB    NOT NULL,
  sign_count     INTEGER NOT NULL DEFAULT 0 CHECK (sign_count >= 0),
  name           TEXT    NOT NULL,
  transports     TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(transports)),
  last_used_at   INTEGER,
  created_at     INTEGER NOT NULL,
  updated_at     INTEGER NOT NULL
);
CREATE INDEX idx_admin_webauthn_admin ON admin_webauthn_credentials(admin_id);

-- -----------------------------------------------------------------------------
-- 7. sessions   (not in recon; ADR 0002 D5: session cookie + MFA)
-- -----------------------------------------------------------------------------
CREATE TABLE sessions (
  id                    TEXT    PRIMARY KEY CHECK (length(id) = 26),
  admin_id              TEXT    NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  token_hash            TEXT    NOT NULL UNIQUE CHECK (length(token_hash) = 64 AND token_hash NOT GLOB '*[^0-9a-f]*'),  -- sha256 hex of the cookie value
  mfa_verified_at       INTEGER,                    -- fresh-MFA gate for key reveal and destructive actions
  source_ip             TEXT,
  user_agent_hash       TEXT,
  last_seen_at          INTEGER NOT NULL,
  expires_at            INTEGER NOT NULL,           -- idle timeout
  absolute_expires_at   INTEGER NOT NULL,           -- hard cap
  revoked_at            INTEGER,
  created_at            INTEGER NOT NULL,
  updated_at            INTEGER NOT NULL,
  CHECK (absolute_expires_at >= expires_at)
);
CREATE INDEX idx_sessions_admin   ON sessions(admin_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);

-- -----------------------------------------------------------------------------
-- 8. api_tokens   (recon: ApiToken)
-- -----------------------------------------------------------------------------
CREATE TABLE api_tokens (
  id            TEXT    PRIMARY KEY CHECK (length(id) = 26),
  admin_id      TEXT    NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  name          TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  scopes        TEXT    NOT NULL CHECK (json_valid(scopes)),
  token_prefix  TEXT    NOT NULL,                   -- first 8 chars, for display only
  token_hash    TEXT    NOT NULL UNIQUE CHECK (length(token_hash) = 64 AND token_hash NOT GLOB '*[^0-9a-f]*'),
  last_used_at  INTEGER,
  expires_at    INTEGER,
  revoked_at    INTEGER,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
);
CREATE INDEX idx_api_tokens_admin ON api_tokens(admin_id);
CREATE UNIQUE INDEX uq_api_tokens_active_name ON api_tokens(admin_id, name) WHERE revoked_at IS NULL;

-- -----------------------------------------------------------------------------
-- 9. policies   (recon: Policy)  customers <-> policies is a circular reference by design
-- -----------------------------------------------------------------------------
CREATE TABLE policies (
  id                      TEXT    PRIMARY KEY CHECK (length(id) = 26),
  scope                   TEXT    NOT NULL CHECK (scope IN ('default','template','customer')),
  customer_id             TEXT    REFERENCES customers(id) ON DELETE CASCADE,   -- a customer-scoped policy dies with its customer
  name                    TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  description             TEXT,
  template_device_class   TEXT    CHECK (template_device_class IN ('laptop','desktop')),
  version                 INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  schedule                TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(schedule)),
  conditions              TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(conditions)),
  selection               TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(selection)),
  retention               TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(retention)),
  throttle                TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(throttle)),
  sla                     TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(sla)),
  maintenance             TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(maintenance)),
  agent_permissions       TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(agent_permissions)),
  notification_overrides  TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(notification_overrides)),
  source_id               TEXT,                     -- non-device sources (M365/GWS), NULL for device policies
  created_by              TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  created_at              INTEGER NOT NULL,
  updated_at              INTEGER NOT NULL,
  CHECK ((scope = 'customer') = (customer_id IS NOT NULL)),
  CHECK (template_device_class IS NULL OR scope = 'template')
);
CREATE UNIQUE INDEX uq_policies_one_default     ON policies(scope) WHERE scope = 'default';
CREATE UNIQUE INDEX uq_policies_shared_name     ON policies(name COLLATE NOCASE) WHERE scope IN ('default','template');
CREATE UNIQUE INDEX uq_policies_customer_name   ON policies(customer_id, name COLLATE NOCASE) WHERE scope = 'customer';
CREATE INDEX idx_policies_customer   ON policies(customer_id);
CREATE INDEX idx_policies_created_by ON policies(created_by);
CREATE INDEX idx_policies_scope      ON policies(scope);

-- -----------------------------------------------------------------------------
-- 10. policy_revisions   (matrix: policy versioning, drift, rollback)
-- -----------------------------------------------------------------------------
CREATE TABLE policy_revisions (
  id           TEXT    PRIMARY KEY CHECK (length(id) = 26),
  policy_id    TEXT    NOT NULL REFERENCES policies(id) ON DELETE CASCADE,
  version      INTEGER NOT NULL CHECK (version >= 1),
  body         TEXT    NOT NULL CHECK (json_valid(body)),     -- the full policy document at that version
  changed_by   TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  change_note  TEXT,
  created_at   INTEGER NOT NULL,
  UNIQUE (policy_id, version)
);
CREATE INDEX idx_policy_revisions_changed_by ON policy_revisions(changed_by);

-- -----------------------------------------------------------------------------
-- 11. customers   (recon: Customer)
-- -----------------------------------------------------------------------------
CREATE TABLE customers (
  id                 TEXT    PRIMARY KEY CHECK (length(id) = 26),
  name               TEXT    NOT NULL COLLATE NOCASE UNIQUE CHECK (length(name) BETWEEN 1 AND 200),
  slug               TEXT    NOT NULL UNIQUE CHECK (length(slug) BETWEEN 1 AND 63 AND slug NOT GLOB '*[^a-z0-9-]*'),
  state              TEXT    NOT NULL DEFAULT 'active' CHECK (state IN ('active','suspended','archived')),
  expected           INTEGER NOT NULL DEFAULT 0 CHECK (expected IN (0,1)),
  onboarding_until   INTEGER,
  contacts           TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(contacts)),
  policy_id          TEXT    REFERENCES policies(id) ON DELETE RESTRICT,                -- NULL = the default policy applies
  storage_target_id  TEXT    NOT NULL REFERENCES storage_targets(id) ON DELETE RESTRICT,
  display_tz         TEXT,                                                              -- IANA zone; NULL = global display_timezone setting
  device_cap         INTEGER CHECK (device_cap IS NULL OR device_cap > 0),
  key_custody        TEXT    NOT NULL DEFAULT 'escrowed' CHECK (key_custody IN ('escrowed','customer_held')),
  notes              TEXT,
  archived_at        INTEGER,
  created_at         INTEGER NOT NULL,
  updated_at         INTEGER NOT NULL,
  CHECK (NOT (state = 'archived' AND expected = 1)),                                    -- an expected customer cannot be archived
  CHECK ((state = 'archived') = (archived_at IS NOT NULL))
);
CREATE INDEX idx_customers_state     ON customers(state);
CREATE INDEX idx_customers_policy    ON customers(policy_id);
CREATE INDEX idx_customers_storage   ON customers(storage_target_id);
CREATE INDEX idx_customers_expected  ON customers(expected) WHERE expected = 1;

-- -----------------------------------------------------------------------------
-- 12. enrollment_tokens   (recon: EnrollmentToken)
-- -----------------------------------------------------------------------------
CREATE TABLE enrollment_tokens (
  id                     TEXT    PRIMARY KEY CHECK (length(id) = 26),
  customer_id            TEXT    NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  label                  TEXT,
  token_hash             TEXT    NOT NULL UNIQUE CHECK (length(token_hash) = 64 AND token_hash NOT GLOB '*[^0-9a-f]*'),
  policy_id              TEXT    REFERENCES policies(id) ON DELETE SET NULL,
  device_class_default   TEXT    NOT NULL DEFAULT 'unknown' CHECK (device_class_default IN ('laptop','desktop','unknown')),
  adopts_device_id       TEXT    REFERENCES devices(id) ON DELETE CASCADE,        -- replace-device tokens (F21); dies with the device so it can never degrade into a plain customer token
  expires_at             INTEGER NOT NULL,
  max_uses               INTEGER CHECK (max_uses IS NULL OR max_uses >= 1),       -- NULL = unlimited
  used_count             INTEGER NOT NULL DEFAULT 0 CHECK (used_count >= 0),
  server_fingerprint     TEXT,                                                    -- TLS SPKI pin carried in the installer (trust on first use)
  created_by             TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  revoked_at             INTEGER,
  created_at             INTEGER NOT NULL,
  updated_at             INTEGER NOT NULL,
  CHECK (max_uses IS NULL OR used_count <= max_uses),
  CHECK (adopts_device_id IS NULL OR COALESCE(max_uses, 0) = 1)           -- NULL = unlimited must not slip through
);
CREATE INDEX idx_enrollment_tokens_customer ON enrollment_tokens(customer_id);
CREATE INDEX idx_enrollment_tokens_policy   ON enrollment_tokens(policy_id);
CREATE INDEX idx_enrollment_tokens_adopts   ON enrollment_tokens(adopts_device_id);
CREATE INDEX idx_enrollment_tokens_creator  ON enrollment_tokens(created_by);
CREATE INDEX idx_enrollment_tokens_expires  ON enrollment_tokens(expires_at) WHERE revoked_at IS NULL;

-- -----------------------------------------------------------------------------
-- 13. devices   (recon: Device)  NO status column: state is computed at read time (ADR D10)
--     Device.last_seen_at lives in device_presence (written every heartbeat).
-- -----------------------------------------------------------------------------
CREATE TABLE devices (
  id                       TEXT    PRIMARY KEY CHECK (length(id) = 26),            -- also the restic --host and the gateway username
  customer_id              TEXT    NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,
  source_kind              TEXT    NOT NULL DEFAULT 'windows_endpoint' CHECK (source_kind IN ('windows_endpoint','m365_tenant','gws_domain')),  -- only windows_endpoint is implemented in v1
  hostname                 TEXT    NOT NULL,
  friendly_name            TEXT,
  os_version               TEXT,
  arch                     TEXT    CHECK (arch IN ('amd64','arm64','x86')),
  device_class             TEXT    NOT NULL DEFAULT 'unknown' CHECK (device_class IN ('laptop','desktop','unknown')),
  agent_version            TEXT,
  restic_version           TEXT,
  update_ring              TEXT    NOT NULL DEFAULT 'stable' CHECK (update_ring IN ('stable','pilot')),
  target_version           TEXT,
  enrolled_at              INTEGER NOT NULL CHECK (enrolled_at >= 1000000000000),   -- time of the CURRENT enrollment; reset when new hardware adopts the identity (F21); history is in audit_events
  enrolled_via             TEXT    NOT NULL CHECK (enrolled_via IN ('token','lobby','adoption','import')),
  enrollment_token_id      TEXT    REFERENCES enrollment_tokens(id) ON DELETE SET NULL,
  enroll_nonce             TEXT    UNIQUE,                                          -- agent-generated; makes enroll retries idempotent
  enroll_confirmed_at      INTEGER,                                                 -- first authenticated call after enroll (policy pull or heartbeat)
  first_backup_due_by      INTEGER,                                                 -- end of first-backup grace; reset on re-enroll / replacement
  policy_version_applied   INTEGER CHECK (policy_version_applied IS NULL OR policy_version_applied >= 1),
  paused_at                INTEGER,                                                 -- console-owned pause (B15)
  paused_until             INTEGER,                                                 -- NULL while paused_at is set = indefinite
  pause_reason             TEXT,
  paused_by                TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  retired_at               INTEGER,
  retired_reason           TEXT,
  replaced_by_device_id    TEXT    REFERENCES devices(id) ON DELETE SET NULL,
  repo_path                TEXT    NOT NULL UNIQUE,                                 -- <prefix>/<device_id>/ relative to the storage target
  hw_fingerprint           TEXT,                                                    -- opaque hash, cloned-identity detection
  identity_conflict_at     INTEGER,                                                 -- set when a second machine presents this identity
  notes                    TEXT,
  created_at               INTEGER NOT NULL,
  updated_at               INTEGER NOT NULL,
  CHECK (NOT (retired_at IS NOT NULL AND paused_at IS NOT NULL)),                   -- a device may not be both retired and paused
  CHECK (paused_until IS NULL OR (paused_at IS NOT NULL AND paused_until > paused_at)),
  CHECK (paused_at IS NULL OR (pause_reason IS NOT NULL AND length(pause_reason) > 0)),
  CHECK (replaced_by_device_id IS NULL OR replaced_by_device_id <> id),
  CHECK (replaced_by_device_id IS NULL OR retired_at IS NOT NULL)                   -- "replaced" is a kind of retired
);
CREATE INDEX idx_devices_customer        ON devices(customer_id);
CREATE INDEX idx_devices_customer_active ON devices(customer_id) WHERE retired_at IS NULL;
CREATE INDEX idx_devices_hostname        ON devices(hostname COLLATE NOCASE);
CREATE INDEX idx_devices_enrollment_tok  ON devices(enrollment_token_id);
CREATE INDEX idx_devices_replaced_by     ON devices(replaced_by_device_id);
CREATE INDEX idx_devices_paused_by       ON devices(paused_by);
CREATE INDEX idx_devices_hw_fingerprint  ON devices(hw_fingerprint);
CREATE INDEX idx_devices_ring_version    ON devices(update_ring, agent_version);
CREATE INDEX idx_devices_paused          ON devices(paused_until) WHERE paused_at IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 14. device_tokens   (ADR D5: hashed, rotatable bearer tokens)
--     One CURRENT token per device; a superseded token stays valid until grace_until
--     so a lost rotation response cannot lock an agent out.
-- -----------------------------------------------------------------------------
CREATE TABLE device_tokens (
  id              TEXT    PRIMARY KEY CHECK (length(id) = 26),
  device_id       TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  token_hash      TEXT    NOT NULL UNIQUE CHECK (length(token_hash) = 64 AND token_hash NOT GLOB '*[^0-9a-f]*'),
  superseded_at   INTEGER,
  grace_until     INTEGER,
  expires_at      INTEGER,
  last_used_at    INTEGER,
  last_used_ip    TEXT,
  revoked_at      INTEGER,
  revoked_reason  TEXT,
  created_at      INTEGER NOT NULL,
  updated_at      INTEGER NOT NULL,
  CHECK ((superseded_at IS NULL) = (grace_until IS NULL))
);
CREATE INDEX idx_device_tokens_device ON device_tokens(device_id);
CREATE UNIQUE INDEX uq_device_tokens_current ON device_tokens(device_id) WHERE revoked_at IS NULL AND superseded_at IS NULL;

-- -----------------------------------------------------------------------------
-- 15. device_presence   (recon: Heartbeat "latest row"; upserted every heartbeat)
-- -----------------------------------------------------------------------------
CREATE TABLE device_presence (
  device_id         TEXT    PRIMARY KEY REFERENCES devices(id) ON DELETE CASCADE,
  received_at       INTEGER NOT NULL CHECK (received_at >= 1000000000000),         -- server clock; this is Device.last_seen_at
  agent_version     TEXT,
  uptime_s          INTEGER CHECK (uptime_s IS NULL OR uptime_s >= 0),
  on_ac             INTEGER CHECK (on_ac IN (0,1)),
  battery_pct       INTEGER CHECK (battery_pct IS NULL OR battery_pct BETWEEN 0 AND 100),
  metered           INTEGER CHECK (metered IN (0,1)),
  vpn               INTEGER CHECK (vpn IN (0,1)),
  queue_depth       INTEGER CHECK (queue_depth IS NULL OR queue_depth >= 0),
  journal_depth     INTEGER CHECK (journal_depth IS NULL OR journal_depth >= 0),
  clock_offset_ms   INTEGER,                                                       -- device clock minus server clock
  service_state     TEXT    NOT NULL CHECK (service_state IN ('idle','running','paused','deferred')),
  last_error_class  TEXT,
  progress          TEXT    CHECK (progress IS NULL OR json_valid(progress)),      -- live run progress (counts only, no paths)
  source_ip         TEXT,
  created_at        INTEGER NOT NULL,
  updated_at        INTEGER NOT NULL
);
CREATE INDEX idx_device_presence_received ON device_presence(received_at);

-- -----------------------------------------------------------------------------
-- 16. heartbeats   (recon: Heartbeat "short ring"; trimmed to heartbeat_ring_hours)
-- -----------------------------------------------------------------------------
CREATE TABLE heartbeats (
  id               TEXT    PRIMARY KEY CHECK (length(id) = 26),
  device_id        TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  received_at      INTEGER NOT NULL CHECK (received_at >= 1000000000000),
  agent_version    TEXT,
  uptime_s         INTEGER CHECK (uptime_s IS NULL OR uptime_s >= 0),
  on_ac            INTEGER CHECK (on_ac IN (0,1)),
  battery_pct      INTEGER CHECK (battery_pct IS NULL OR battery_pct BETWEEN 0 AND 100),
  metered          INTEGER CHECK (metered IN (0,1)),
  vpn              INTEGER CHECK (vpn IN (0,1)),
  queue_depth      INTEGER CHECK (queue_depth IS NULL OR queue_depth >= 0),
  journal_depth    INTEGER CHECK (journal_depth IS NULL OR journal_depth >= 0),
  clock_offset_ms  INTEGER,
  service_state    TEXT    NOT NULL CHECK (service_state IN ('idle','running','paused','deferred')),
  last_error_class TEXT,
  created_at       INTEGER NOT NULL                                               -- insertion time; equals received_at except for imports
);
CREATE INDEX idx_heartbeats_device_received ON heartbeats(device_id, received_at DESC);
CREATE INDEX idx_heartbeats_received        ON heartbeats(received_at);

-- -----------------------------------------------------------------------------
-- 17. enrollment_requests   (lobby: pending-approval enrollment, matrix: should)
-- -----------------------------------------------------------------------------
CREATE TABLE enrollment_requests (
  id               TEXT    PRIMARY KEY CHECK (length(id) = 26),
  request_nonce    TEXT    NOT NULL UNIQUE,
  hostname         TEXT    NOT NULL,
  os_version       TEXT,
  arch             TEXT    CHECK (arch IN ('amd64','arm64','x86')),
  hw_fingerprint   TEXT,
  source_ip        TEXT,
  facts            TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(facts)),
  status           TEXT    NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','expired')),
  customer_id      TEXT    REFERENCES customers(id) ON DELETE SET NULL,           -- chosen at approval
  device_id        TEXT    REFERENCES devices(id) ON DELETE SET NULL,
  decided_by       TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  decided_at       INTEGER,
  expires_at       INTEGER NOT NULL,
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL,
  CHECK (status <> 'approved' OR (customer_id IS NOT NULL AND decided_at IS NOT NULL)),
  CHECK (status NOT IN ('approved','rejected') OR decided_at IS NOT NULL)
);
CREATE INDEX idx_enrollment_requests_status   ON enrollment_requests(status, created_at DESC);
CREATE INDEX idx_enrollment_requests_customer ON enrollment_requests(customer_id);
CREATE INDEX idx_enrollment_requests_device   ON enrollment_requests(device_id);
CREATE INDEX idx_enrollment_requests_decider  ON enrollment_requests(decided_by);

-- -----------------------------------------------------------------------------
-- 18. gateway_logins   (recon: GatewayLogin)  username == device id (rclone --private-repos)
--     pending_secret_wrapped holds the plaintext password ONLY between rotation and
--     the agent's acknowledged delivery (delivered_at), then it is set to NULL.
-- -----------------------------------------------------------------------------
CREATE TABLE gateway_logins (
  id                     TEXT    PRIMARY KEY CHECK (length(id) = 26),
  device_id              TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  username               TEXT    NOT NULL CHECK (length(username) = 26),
  password_hash          TEXT    NOT NULL CHECK (length(password_hash) = 60 AND password_hash GLOB '$2[aby]$[0-9][0-9]$*'),   -- bcrypt, htpasswd-compatible
  pending_secret_wrapped BLOB,
  delivered_at           INTEGER,
  rotated_at             INTEGER,
  revoked_at             INTEGER,
  htpasswd_synced_at     INTEGER,
  created_at             INTEGER NOT NULL,
  updated_at             INTEGER NOT NULL,
  CHECK (pending_secret_wrapped IS NULL OR delivered_at IS NULL)
);
CREATE INDEX idx_gateway_logins_device ON gateway_logins(device_id);
CREATE UNIQUE INDEX uq_gateway_logins_active_device   ON gateway_logins(device_id) WHERE revoked_at IS NULL;   -- one active login per device
CREATE UNIQUE INDEX uq_gateway_logins_active_username ON gateway_logins(username)  WHERE revoked_at IS NULL;
CREATE INDEX idx_gateway_logins_unsynced ON gateway_logins(htpasswd_synced_at) WHERE htpasswd_synced_at IS NULL;

-- -----------------------------------------------------------------------------
-- 19. repo_key_escrow   (recon: RepoKeyEscrow)
-- -----------------------------------------------------------------------------
CREATE TABLE repo_key_escrow (
  id                       TEXT    PRIMARY KEY CHECK (length(id) = 26),
  device_id                TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  key_version              INTEGER NOT NULL CHECK (key_version >= 1),
  custody                  TEXT    NOT NULL CHECK (custody IN ('escrowed','customer_held')),
  wrapped_key              BLOB,
  wrap_alg                 TEXT    CHECK (wrap_alg IN ('aes-256-gcm+hkdf-sha256/v1')),
  master_key_id            TEXT,                                                -- which master-key generation wrapped it (rotation re-wraps)
  verified_at              INTEGER,                                             -- last successful `restic cat config` with the unwrapped key
  last_verify_attempt_at   INTEGER,
  last_verify_error_class  TEXT,
  retired_at               INTEGER,
  created_at               INTEGER NOT NULL,
  updated_at               INTEGER NOT NULL,
  UNIQUE (device_id, key_version),
  CHECK ((custody = 'escrowed' AND wrapped_key IS NOT NULL AND wrap_alg IS NOT NULL AND master_key_id IS NOT NULL)
      OR (custody = 'customer_held' AND wrapped_key IS NULL AND verified_at IS NULL))
);
CREATE INDEX idx_repo_key_escrow_device ON repo_key_escrow(device_id);
CREATE UNIQUE INDEX uq_repo_key_escrow_active ON repo_key_escrow(device_id) WHERE retired_at IS NULL;          -- one active key per device
CREATE INDEX idx_repo_key_escrow_unverified ON repo_key_escrow(verified_at) WHERE retired_at IS NULL AND custody = 'escrowed';
CREATE INDEX idx_repo_key_escrow_master ON repo_key_escrow(master_key_id);

-- -----------------------------------------------------------------------------
-- 20. device_policy_overrides   (recon: DevicePolicyOverride)  patch = RFC 7386 JSON merge patch
-- -----------------------------------------------------------------------------
CREATE TABLE device_policy_overrides (
  id          TEXT    PRIMARY KEY CHECK (length(id) = 26),
  device_id   TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  patch       TEXT    NOT NULL CHECK (json_valid(patch)),
  reason      TEXT    NOT NULL CHECK (length(reason) > 0),
  set_by      TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  expires_at  INTEGER,
  cleared_at  INTEGER,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
);
CREATE INDEX idx_device_policy_overrides_device ON device_policy_overrides(device_id);
CREATE INDEX idx_device_policy_overrides_setter ON device_policy_overrides(set_by);
CREATE UNIQUE INDEX uq_device_policy_overrides_active ON device_policy_overrides(device_id) WHERE cleared_at IS NULL;   -- one active override per device

-- -----------------------------------------------------------------------------
-- 21. runs   (recon: Run)  agent runs (origin 'agent') and console maintenance runs (origin 'console')
--     started_at / finished_at are SERVER-time (device time minus clock_offset_ms at ingest, clamped to
--     received_at). outcome IS NULL means the run is open (in progress or not yet finished).
--     snapshot_id is NOT a foreign key: it is a repository id, snapshots is only a cache that forget
--     prunes, and the run row must outlive it.
-- -----------------------------------------------------------------------------
CREATE TABLE runs (
  id               TEXT    PRIMARY KEY CHECK (length(id) = 26),                    -- agent-generated ULID = idempotency key (unique run id)
  device_id        TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  origin           TEXT    NOT NULL DEFAULT 'agent' CHECK (origin IN ('agent','console')),
  kind             TEXT    NOT NULL CHECK (kind IN ('backup','restore','forget','prune','check','unlock','maintenance')),
  trigger_kind     TEXT    NOT NULL CHECK (trigger_kind IN ('schedule','catchup','wake','boot','manual','retry')),
  started_at       INTEGER NOT NULL CHECK (started_at >= 1000000000000),
  finished_at      INTEGER CHECK (finished_at IS NULL OR finished_at >= 1000000000000),
  received_at      INTEGER NOT NULL CHECK (received_at >= 1000000000000),
  clock_offset_ms  INTEGER NOT NULL DEFAULT 0,
  outcome          TEXT    CHECK (outcome IN ('success','partial','failed','cancelled','skipped','deferred','interrupted','abandoned')),
  restic_exit_code INTEGER,
  snapshot_id      TEXT    CHECK (snapshot_id IS NULL OR (length(snapshot_id) = 64 AND snapshot_id NOT GLOB '*[^0-9a-f]*')),
  stats            TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(stats)),
  data_added_bytes INTEGER CHECK (data_added_bytes IS NULL OR data_added_bytes >= 0),
  error_counts     TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(error_counts)),  -- {class: n}; never paths or messages
  error_class      TEXT    CHECK (error_class IN ('network','tls','auth','lock','vss','disk','permission','memory','repo_missing','wrong_password','storage','parse','guard_refused','internal','unknown','locked','missing_source','unsupported_file')),
  attempt          INTEGER NOT NULL DEFAULT 1 CHECK (attempt >= 1),
  deferred_reason  TEXT    CHECK (deferred_reason IN ('lock','gateway','battery','metered','window','conditions','fleet_cap')),
  policy_version   INTEGER CHECK (policy_version IS NULL OR policy_version >= 1),
  agent_version    TEXT,
  source_id        TEXT,                                                           -- non-device sources; NULL for device runs
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL,
  CHECK (finished_at IS NULL OR finished_at >= started_at),
  CHECK ((outcome IS NULL) = (finished_at IS NULL)),                                -- open iff no outcome
  CHECK (outcome <> 'deferred' OR deferred_reason IS NOT NULL),
  CHECK (deferred_reason IS NULL OR COALESCE(outcome, '') = 'deferred'),
  CHECK (snapshot_id IS NULL OR kind = 'backup')
);
CREATE INDEX idx_runs_device_started   ON runs(device_id, started_at DESC);
CREATE INDEX idx_runs_started          ON runs(started_at DESC);
CREATE INDEX idx_runs_kind_started     ON runs(kind, started_at DESC);
CREATE INDEX idx_runs_outcome_started  ON runs(outcome, started_at DESC);
CREATE INDEX idx_runs_open             ON runs(device_id, started_at) WHERE outcome IS NULL;
CREATE INDEX idx_runs_last_success     ON runs(device_id, finished_at DESC) WHERE kind = 'backup' AND outcome = 'success';
CREATE INDEX idx_runs_last_backup_done ON runs(device_id, finished_at DESC) WHERE kind = 'backup' AND outcome IS NOT NULL;
CREATE INDEX idx_runs_maint_done       ON runs(device_id, kind, finished_at DESC) WHERE kind IN ('forget','prune','check') AND outcome IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 22. snapshots   (recon: Snapshot)  cache of `restic snapshots --json`; the repository is authoritative
--     paths = backup ROOTS as passed to restic (policy-defined), never file-level paths.
-- -----------------------------------------------------------------------------
CREATE TABLE snapshots (
  device_id        TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  snapshot_id      TEXT    NOT NULL CHECK (length(snapshot_id) = 64 AND snapshot_id NOT GLOB '*[^0-9a-f]*'),
  taken_at         INTEGER NOT NULL CHECK (taken_at >= 1000000000000),
  parent_id        TEXT,
  hostname         TEXT,
  paths            TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(paths)),
  tags             TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(tags)),
  program_version  TEXT,
  summary          TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(summary)),
  source_id        TEXT,
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL,
  PRIMARY KEY (device_id, snapshot_id)                                              -- unique (device_id, snapshot_id)
) WITHOUT ROWID;
CREATE INDEX idx_snapshots_device_taken ON snapshots(device_id, taken_at DESC);

-- -----------------------------------------------------------------------------
-- 23. usage_samples   (recon: UsageSample)  one sample per device per hour bucket (idempotent upsert)
-- -----------------------------------------------------------------------------
CREATE TABLE usage_samples (
  device_id           TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  sampled_at          INTEGER NOT NULL CHECK (sampled_at >= 1000000000000),
  repo_bytes          INTEGER NOT NULL CHECK (repo_bytes >= 0),
  restore_size_bytes  INTEGER CHECK (restore_size_bytes IS NULL OR restore_size_bytes >= 0),
  snapshot_count      INTEGER CHECK (snapshot_count IS NULL OR snapshot_count >= 0),
  blob_count          INTEGER CHECK (blob_count IS NULL OR blob_count >= 0),
  source              TEXT    NOT NULL CHECK (source IN ('restic_stats','provider')),
  created_at          INTEGER NOT NULL,
  updated_at          INTEGER NOT NULL,
  PRIMARY KEY (device_id, sampled_at)
) WITHOUT ROWID;
CREATE INDEX idx_usage_samples_sampled ON usage_samples(sampled_at);

-- -----------------------------------------------------------------------------
-- 24. maintenance_schedule   (D8: per-device forget/prune/check cadence and lease)
-- -----------------------------------------------------------------------------
CREATE TABLE maintenance_schedule (
  device_id              TEXT    PRIMARY KEY REFERENCES devices(id) ON DELETE CASCADE,
  enabled                INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),     -- 0 for customer-held devices (no key on the server)
  last_forget_at         INTEGER,
  last_prune_at          INTEGER,
  last_check_at          INTEGER,
  next_forget_after      INTEGER,
  next_prune_after       INTEGER,
  next_check_after       INTEGER,
  deferred_count         INTEGER NOT NULL DEFAULT 0 CHECK (deferred_count >= 0),
  last_deferred_at       INTEGER,
  consecutive_failures   INTEGER NOT NULL DEFAULT 0 CHECK (consecutive_failures >= 0),
  lease_holder           TEXT,
  lease_until            INTEGER,
  created_at             INTEGER NOT NULL,
  updated_at             INTEGER NOT NULL,
  CHECK ((lease_holder IS NULL) = (lease_until IS NULL))
);
CREATE INDEX idx_maint_next_forget ON maintenance_schedule(next_forget_after) WHERE enabled = 1;
CREATE INDEX idx_maint_next_prune  ON maintenance_schedule(next_prune_after)  WHERE enabled = 1;
CREATE INDEX idx_maint_next_check  ON maintenance_schedule(next_check_after)  WHERE enabled = 1;

-- -----------------------------------------------------------------------------
-- 25. commands   (recon: Command)  pull-based, idempotent, expiring
-- -----------------------------------------------------------------------------
CREATE TABLE commands (
  id               TEXT    PRIMARY KEY CHECK (length(id) = 26),
  device_id        TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  type             TEXT    NOT NULL CHECK (type IN ('backup_now','cancel','refresh_policy','restart_service','update_agent','pause','resume','hold','restore','check_in','uninstall')),
  params           TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(params)),      -- never contains paths; restore carries only a restore_request id
  idempotency_key  TEXT    NOT NULL CHECK (length(idempotency_key) BETWEEN 1 AND 128),
  status           TEXT    NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','delivered','acked','succeeded','failed','expired','cancelled')),
  created_by       TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,         -- NULL = system (maintenance hold, release rollout)
  expires_at       INTEGER NOT NULL,
  delivered_at     INTEGER,
  acked_at         INTEGER,
  completed_at     INTEGER,
  result           TEXT    CHECK (result IS NULL OR json_valid(result)),
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL,
  UNIQUE (device_id, idempotency_key),                                             -- unique command idempotency key
  CHECK (expires_at > created_at)
);
CREATE INDEX idx_commands_device_status ON commands(device_id, status);
CREATE INDEX idx_commands_status_expiry ON commands(status, expires_at);
CREATE INDEX idx_commands_creator       ON commands(created_by);

-- -----------------------------------------------------------------------------
-- 26. restore_requests   (recon: RestoreRequest)  selection paths exist only as an encrypted,
--     purge-dated blob; counts and a hash persist for audit.
-- -----------------------------------------------------------------------------
CREATE TABLE restore_requests (
  id                 TEXT    PRIMARY KEY CHECK (length(id) = 26),
  device_id          TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  snapshot_id        TEXT    NOT NULL CHECK (length(snapshot_id) = 64 AND snapshot_id NOT GLOB '*[^0-9a-f]*'),
  target_device_id   TEXT    REFERENCES devices(id) ON DELETE CASCADE,            -- device_relay only: the replacement device that pulls the artifact (F08, F21 data-only path)
  mode               TEXT    NOT NULL CHECK (mode IN ('device_original','device_path','device_relay','download_zip','download_tar')),
  overwrite          TEXT    NOT NULL DEFAULT 'if-changed' CHECK (overwrite IN ('always','if-changed','if-newer','never')),
  verify             INTEGER NOT NULL DEFAULT 0 CHECK (verify IN (0,1)),
  simulate           INTEGER NOT NULL DEFAULT 0 CHECK (simulate IN (0,1)),
  selection_count    INTEGER NOT NULL DEFAULT 0 CHECK (selection_count >= 0),
  selection_hash     TEXT,
  selection_wrapped  BLOB,                                                        -- NULL once purged
  status             TEXT    NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','ready','delivered','failed','cancelled','expired','purged')),
  requested_by       TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  command_id         TEXT    REFERENCES commands(id) ON DELETE SET NULL,          -- device restores ride the command queue
  artifact_ref       TEXT,                                                        -- server-side temp file name for downloads
  bytes              INTEGER CHECK (bytes IS NULL OR bytes >= 0),
  progress           TEXT    CHECK (progress IS NULL OR json_valid(progress)),
  error_class        TEXT,
  started_at         INTEGER,
  finished_at        INTEGER,
  expires_at         INTEGER NOT NULL,
  purge_after        INTEGER,
  download_count     INTEGER NOT NULL DEFAULT 0 CHECK (download_count >= 0),
  created_at         INTEGER NOT NULL,
  updated_at         INTEGER NOT NULL,
  CHECK (artifact_ref IS NULL OR purge_after IS NOT NULL),
  CHECK (mode IN ('download_zip','download_tar','device_relay') OR artifact_ref IS NULL),
  CHECK ((mode = 'device_relay') = (target_device_id IS NOT NULL)),
  CHECK (target_device_id IS NULL OR target_device_id <> device_id),
  CHECK (NOT (simulate = 1 AND verify = 1))                                       -- restic: --verify cannot combine with --dry-run
);
CREATE INDEX idx_restore_requests_device_created ON restore_requests(device_id, created_at DESC);
CREATE INDEX idx_restore_requests_status         ON restore_requests(status, expires_at);
CREATE INDEX idx_restore_requests_requester      ON restore_requests(requested_by);
CREATE INDEX idx_restore_requests_command        ON restore_requests(command_id);
CREATE INDEX idx_restore_requests_target         ON restore_requests(target_device_id);
CREATE INDEX idx_restore_requests_purge          ON restore_requests(purge_after) WHERE purge_after IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 27. alarm_acks   (recon: AlarmAck)  the only persisted alarm datum; alarm STATE is computed.
--     An ack never hides an alarm; it mutes notifications and labels it.
-- -----------------------------------------------------------------------------
CREATE TABLE alarm_acks (
  id                          TEXT    PRIMARY KEY CHECK (length(id) = 26),
  subject_type                TEXT    NOT NULL CHECK (subject_type IN ('device','customer')),
  device_id                   TEXT    REFERENCES devices(id) ON DELETE CASCADE,
  customer_id                 TEXT    REFERENCES customers(id) ON DELETE CASCADE,
  alarm_type                  TEXT    NOT NULL CHECK (alarm_type IN ('blank','stuck','failed','partial','unseen','stale','first_backup_overdue','missing_customer','maintenance','escrow','identity','quota','outdated','unknown_state')),
  acknowledged_by             TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  acknowledged_at             INTEGER NOT NULL,
  note                        TEXT,
  snooze_until                INTEGER,
  snooze_until_next_success   INTEGER NOT NULL DEFAULT 0 CHECK (snooze_until_next_success IN (0,1)),
  cleared_at                  INTEGER,
  created_at                  INTEGER NOT NULL,
  updated_at                  INTEGER NOT NULL,
  CHECK ((subject_type = 'device' AND device_id IS NOT NULL AND customer_id IS NULL)
      OR (subject_type = 'customer' AND customer_id IS NOT NULL AND device_id IS NULL))
);
CREATE INDEX idx_alarm_acks_device   ON alarm_acks(device_id);
CREATE INDEX idx_alarm_acks_customer ON alarm_acks(customer_id);
CREATE INDEX idx_alarm_acks_admin    ON alarm_acks(acknowledged_by);
CREATE UNIQUE INDEX uq_alarm_acks_active_device   ON alarm_acks(device_id, alarm_type)   WHERE cleared_at IS NULL AND device_id IS NOT NULL;
CREATE UNIQUE INDEX uq_alarm_acks_active_customer ON alarm_acks(customer_id, alarm_type) WHERE cleared_at IS NULL AND customer_id IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 28. notification_rules   (recon: NotificationRule)  secrets (headers, tokens) are wrapped
-- -----------------------------------------------------------------------------
CREATE TABLE notification_rules (
  id                   TEXT    PRIMARY KEY CHECK (length(id) = 26),
  scope                TEXT    NOT NULL CHECK (scope IN ('global','customer','device')),
  customer_id          TEXT    REFERENCES customers(id) ON DELETE CASCADE,
  device_id            TEXT    REFERENCES devices(id) ON DELETE CASCADE,
  name                 TEXT    NOT NULL,
  channel              TEXT    NOT NULL CHECK (channel IN ('email','webhook','rmm')),
  destination          TEXT    NOT NULL,                                          -- address, URL (no credentials), or adapter name
  config               TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(config)), -- payload format, event whitelist, ...
  secret_wrapped       BLOB,                                                      -- header values / API token
  triggers             TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(triggers)),
  min_severity         TEXT    NOT NULL DEFAULT 'warning' CHECK (min_severity IN ('info','warning','critical')),
  digest_schedule      TEXT,
  nag_interval_minutes INTEGER CHECK (nag_interval_minutes IS NULL OR nag_interval_minutes > 0),
  failure_threshold    INTEGER NOT NULL DEFAULT 1 CHECK (failure_threshold >= 1),
  notify_recovery      INTEGER NOT NULL DEFAULT 1 CHECK (notify_recovery IN (0,1)),
  enabled              INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  created_at           INTEGER NOT NULL,
  updated_at           INTEGER NOT NULL,
  CHECK ((scope = 'global'   AND customer_id IS NULL     AND device_id IS NULL)
      OR (scope = 'customer' AND customer_id IS NOT NULL AND device_id IS NULL)
      OR (scope = 'device'   AND device_id   IS NOT NULL AND customer_id IS NULL))
);
CREATE INDEX idx_notification_rules_customer ON notification_rules(customer_id);
CREATE INDEX idx_notification_rules_device   ON notification_rules(device_id);
CREATE INDEX idx_notification_rules_enabled  ON notification_rules(enabled, channel);

-- -----------------------------------------------------------------------------
-- 29. notification_log   (recon: NotificationLog)  feeds dedupe, nag and the delivery-failure alarm
-- -----------------------------------------------------------------------------
CREATE TABLE notification_log (
  id               TEXT    PRIMARY KEY CHECK (length(id) = 26),
  rule_id          TEXT    REFERENCES notification_rules(id) ON DELETE SET NULL,     -- the log outlives the rule
  dedupe_key       TEXT    NOT NULL,
  kind             TEXT    NOT NULL CHECK (kind IN ('alert','recovery','nag','digest','report','test','event')),
  subject_type     TEXT    NOT NULL CHECK (subject_type IN ('device','customer','console')),
  subject_id       TEXT,
  channel          TEXT    NOT NULL CHECK (channel IN ('email','webhook','rmm')),
  result           TEXT    NOT NULL CHECK (result IN ('queued','sent','failed','suppressed')),
  suppress_reason  TEXT    CHECK (suppress_reason IN ('acknowledged','snoozed','paused','deduped','customer_suspended','below_threshold')),
  error_class      TEXT,
  attempt          INTEGER NOT NULL DEFAULT 1 CHECK (attempt >= 1),
  next_retry_at    INTEGER,
  sent_at          INTEGER NOT NULL CHECK (sent_at >= 1000000000000),               -- time of the attempt / decision
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL,
  CHECK (suppress_reason IS NULL OR result = 'suppressed')
);
CREATE INDEX idx_notification_log_dedupe  ON notification_log(dedupe_key, sent_at DESC);
CREATE INDEX idx_notification_log_rule    ON notification_log(rule_id);
CREATE INDEX idx_notification_log_subject ON notification_log(subject_type, subject_id, sent_at DESC);
CREATE INDEX idx_notification_log_failed  ON notification_log(sent_at DESC) WHERE result = 'failed';

-- -----------------------------------------------------------------------------
-- 30. saved_views   (recon: SavedView)
--    audience (migration 0005, M3-T3): who besides the owner sees a shared view:
--    'all' (accounts that see every customer only) or a JSON array of customer
--    ids (accounts whose scope holds every one); NULL for a private view. It sits
--    on the updated_at line because that is where SQLite's ALTER TABLE ... ADD
--    COLUMN writes it in sqlite_master, and the migrated schema must equal this
--    file (DH20).
-- -----------------------------------------------------------------------------
CREATE TABLE saved_views (
  id          TEXT    PRIMARY KEY CHECK (length(id) = 26),
  owner_id    TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  name        TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  entity      TEXT    NOT NULL CHECK (entity IN ('devices','runs','customers')),
  filter      TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(filter)),               -- clause tree
  columns     TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(columns)),
  sort        TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(sort)),
  shared      INTEGER NOT NULL DEFAULT 0 CHECK (shared IN (0,1)),
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL, audience TEXT CHECK (audience IS NULL OR audience = 'all' OR (json_valid(audience) AND json_type(audience) = 'array')),
  UNIQUE (owner_id, entity, name)
);
CREATE INDEX idx_saved_views_owner  ON saved_views(owner_id);
CREATE INDEX idx_saved_views_shared ON saved_views(shared, entity);

-- -----------------------------------------------------------------------------
-- 31. reports   (recon: Report)
-- -----------------------------------------------------------------------------
CREATE TABLE reports (
  id             TEXT    PRIMARY KEY CHECK (length(id) = 26),
  name           TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  scope          TEXT    NOT NULL CHECK (scope IN ('global','customer')),
  customer_id    TEXT    REFERENCES customers(id) ON DELETE CASCADE,
  saved_view_id  TEXT    REFERENCES saved_views(id) ON DELETE SET NULL,
  kind           TEXT    NOT NULL CHECK (kind IN ('customer_status','storage_usage','compliance','inventory','device_list','run_log','grouped_status','recent_activity')),
  layout         TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(layout)),
  format         TEXT    NOT NULL CHECK (format IN ('html','pdf','csv','xlsx')),
  schedule       TEXT,                                                              -- NULL = on demand only
  recipients     TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(recipients)),
  active         INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  last_run_at    INTEGER,
  last_result    TEXT    CHECK (last_result IN ('ok','failed')),
  created_by     TEXT    REFERENCES admin_users(id) ON DELETE SET NULL,
  created_at     INTEGER NOT NULL,
  updated_at     INTEGER NOT NULL,
  CHECK ((scope = 'customer') = (customer_id IS NOT NULL))
);
CREATE INDEX idx_reports_customer   ON reports(customer_id);
CREATE INDEX idx_reports_view       ON reports(saved_view_id);
CREATE INDEX idx_reports_created_by ON reports(created_by);
CREATE INDEX idx_reports_active     ON reports(active, schedule);

-- -----------------------------------------------------------------------------
-- 32. audit_events   (recon: AuditEvent)  NO foreign keys, deliberately: an audit row must outlive
--     the admin, customer and device it describes. actor_id / object_id / customer_id are plain text.
--     Rows are immutable (trigger below); only the retention job deletes, by age.
-- -----------------------------------------------------------------------------
CREATE TABLE audit_events (
  id            TEXT    PRIMARY KEY CHECK (length(id) = 26),
  occurred_at   INTEGER NOT NULL CHECK (occurred_at >= 1000000000000),
  actor_type    TEXT    NOT NULL CHECK (actor_type IN ('admin','api_token','device','system','cli')),
  actor_id      TEXT,
  actor_label   TEXT,                                                               -- username / hostname snapshot
  method        TEXT    NOT NULL CHECK (method IN ('web','api','agent','system','cli')),
  source_ip     TEXT,
  action        TEXT    NOT NULL,
  object_type   TEXT,
  object_id     TEXT,
  customer_id   TEXT,
  result        TEXT    NOT NULL CHECK (result IN ('ok','denied','error')),
  severity      TEXT    NOT NULL DEFAULT 'info' CHECK (severity IN ('info','warning','critical')),
  details       TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(details)),          -- path-free by construction (logx)
  created_at    INTEGER NOT NULL
);
CREATE INDEX idx_audit_occurred ON audit_events(occurred_at DESC);
CREATE INDEX idx_audit_object   ON audit_events(object_type, object_id, occurred_at DESC);
CREATE INDEX idx_audit_customer ON audit_events(customer_id, occurred_at DESC);
CREATE INDEX idx_audit_actor    ON audit_events(actor_id, occurred_at DESC);
CREATE INDEX idx_audit_action   ON audit_events(action, occurred_at DESC);
CREATE TRIGGER trg_audit_events_immutable BEFORE UPDATE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit_events rows are immutable');
END;

-- -----------------------------------------------------------------------------
-- 33. agent_releases   (recon: AgentRelease)  also holds the signed release manifest
--     (decided: no separate release_manifests table).
-- -----------------------------------------------------------------------------
CREATE TABLE agent_releases (
  id               TEXT    PRIMARY KEY CHECK (length(id) = 26),
  version          TEXT    NOT NULL,
  channel          TEXT    NOT NULL CHECK (channel IN ('pilot','stable')),
  sha256           TEXT    NOT NULL CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),      -- of the agent artifact
  signature        TEXT    NOT NULL,                                                  -- detached signature over the manifest
  restic_version   TEXT    NOT NULL,
  restic_sha256    TEXT    NOT NULL CHECK (length(restic_sha256) = 64 AND restic_sha256 NOT GLOB '*[^0-9a-f]*'),
  min_os           TEXT    NOT NULL,
  manifest         TEXT    NOT NULL CHECK (json_valid(manifest)),
  artifact_ref     TEXT    NOT NULL,                                                  -- file name under the operator's releases directory
  released_at      INTEGER NOT NULL,
  withdrawn_at     INTEGER,
  notes            TEXT,
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL,
  UNIQUE (version, channel)
);
CREATE INDEX idx_agent_releases_channel ON agent_releases(channel, released_at DESC);

-- -----------------------------------------------------------------------------
-- 34. job_state   (D13 system health + lease so two processes never run the same job)
-- -----------------------------------------------------------------------------
CREATE TABLE job_state (
  name              TEXT    PRIMARY KEY CHECK (length(name) BETWEEN 1 AND 64),
  last_started_at   INTEGER,
  last_finished_at  INTEGER,
  last_status       TEXT    CHECK (last_status IN ('running','ok','error','skipped')),
  last_error_class  TEXT,
  last_duration_ms  INTEGER CHECK (last_duration_ms IS NULL OR last_duration_ms >= 0),
  run_count         INTEGER NOT NULL DEFAULT 0 CHECK (run_count >= 0),
  lease_holder      TEXT,
  lease_until       INTEGER,
  next_due_at       INTEGER,
  created_at        INTEGER NOT NULL,
  updated_at        INTEGER NOT NULL,
  CHECK ((lease_holder IS NULL) = (lease_until IS NULL))
);
CREATE INDEX idx_job_state_due ON job_state(next_due_at);

-- -----------------------------------------------------------------------------
-- 35. start_leases   (migration 0003, ADR 0005: fleet concurrency cap)
--     One row per live start lease, keyed by the agent's run id. A scheduled
--     backup asks for one before it starts; the console grants while fewer than
--     storage_targets.max_concurrent_backups leases are live for the device's
--     target. 15 minutes, renewed by the heartbeats of the running agent,
--     released by the upload of the closed run; expired rows are deleted when a
--     lease is asked for and by the heartbeat ring trim job.
-- -----------------------------------------------------------------------------
CREATE TABLE start_leases (
  run_id             TEXT    PRIMARY KEY CHECK (length(run_id) = 26),                -- the agent's run id (ULID): one lease per run, the idempotency key
  device_id          TEXT    NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  storage_target_id  TEXT    NOT NULL REFERENCES storage_targets(id) ON DELETE CASCADE,  -- the target whose max_concurrent_backups the lease counts against
  granted_at         INTEGER NOT NULL CHECK (granted_at >= 1000000000000),
  lease_until        INTEGER NOT NULL,                                               -- live while > now; renewed by heartbeats of the running agent
  created_at         INTEGER NOT NULL,
  updated_at         INTEGER NOT NULL,
  CHECK (lease_until > granted_at)
);
CREATE INDEX idx_start_leases_target_until ON start_leases(storage_target_id, lease_until);
CREATE INDEX idx_start_leases_device       ON start_leases(device_id);

